function topbar(title='',back=null){return `<div class="topbar"><div class="row">${back?`<button class="icon-btn" data-go="${back}" aria-label="Back">‹</button>`:''}<div class="brand">${!back?`<span class="brand-mark">${brandSymbol}</span>`:''}<span>${esc(title||'ESAS Reviewer')}</span></div></div><div class="row"><button class="icon-btn" data-action="theme" title="Switch theme" aria-label="Switch theme">${state.theme==='light'?'☾':'☀'}</button><button class="avatar" data-go="profile" aria-label="Profile">${esc((state.profile.name||'G').charAt(0).toUpperCase())}</button></div></div>`}
function bottomNav(){return `<nav class="bottom-nav" aria-label="Main navigation">${nav.map(([id,icon,label])=>`<button class="nav-item ${state.page===id?'active':''}" data-go="${id}" ${state.page===id?'aria-current="page"':''}><b>${icon}</b><span>${label}</span></button>`).join('')}</nav>`}
function title(text,sub='',back=null){return `${topbar(text,back)}<div class="eyebrow">${esc(sub||'YOUR STUDY SPACE')}</div><h1>${esc(text)}</h1>`}
function home(){return `${topbar()}<div class="glass hero"><div class="eyebrow">CONTINUE LEARNING</div><div class="row between"><div class="grow"><h2>Keep your momentum</h2><p class="muted small">Explore a lesson, practice a quiz, and build your own notes.</p><button class="btn" data-go="reviewer">Explore reviewer <span>→</span></button></div><div class="progress-ring"><span>✦</span></div></div></div><div class="section-head"><h2>Quick access</h2><button class="link-button" data-go="more">See all</button></div><div class="grid2">${tile('▥','Reviewer','Lessons & formulas','reviewer','blue')}${tile('▣','Quiz','Practice & mock exams','quiz','violet')}${tile('✓','Practice mode','Instant answer feedback','practice','cyan')}${tile('♛','Rank','Leaderboard · E to SSS','rank','violet')}${tile('∑','Calculator','Calculate on the go','calculator','green')}${tile('▤','Notes','Save what matters','notes','amber')}</div><div class="section-head"><h2>Your learning hub</h2></div><button class="action-row" data-go="sources">${glyph('▧','cyan')}<span class="grow"><strong>Source library</strong><small>${sourceRegistry.length} registered references</small></span><span class="chev">›</span></button><button class="action-row" data-go="support">${glyph('♡','coral')}<span class="grow"><strong>Owner & Support</strong><small>Suggest content or submit a resource</small></span><span class="chev">›</span></button>`}
function tile(icon,name,desc,go,color){return `<button class="tile" data-go="${go}">${glyph(icon,color)}<h3>${name}</h3><p>${desc}</p></button>`}
function searchResults(){let q=state.search.toLowerCase();let found=subjects.filter(s=>s.name.toLowerCase().includes(q)||s.topics.some(t=>t.toLowerCase().includes(q)));return `<div class="section-head"><h2>Search results</h2></div>${found.map(s=>subjectRow(s)).join('')||'<div class="glass empty">No subjects found.</div>'}`}
function subjectRow(s){return `<button class="action-row" data-subject="${s.id}">${glyph(s.icon,s.color)}<span class="grow"><strong>${esc(s.name)}</strong><small>${s.topics.map(esc).join(' · ')}</small></span><span class="chev">›</span></button>`}
function reviewer(){return `${title('Reviewer','EXPLORE & LEARN')}<label class="search"><span>⌕</span><input aria-label="Search subjects" placeholder="Search a subject or topic" data-search="reviewer" value="${esc(state.search)}"></label><div class="chips">${['All','Favorites','Recent','Downloaded','Bookmarks','Resources'].map(f=>`<button class="pill ${state.filter===f?'active':''}" data-filter="${f}">${f}</button>`).join('')}</div>${state.filter==='All'?subjects.filter(s=>!state.search||s.name.toLowerCase().includes(state.search.toLowerCase())||s.topics.some(t=>t.toLowerCase().includes(state.search.toLowerCase()))).map(subjectRow).join('')||'<div class="glass empty">No subjects found.</div>':state.filter==='Resources'?sources():`<div class="glass empty">${glyph('✧','cyan')}<h3>${state.filter}</h3><p>Items you save will appear here.</p><button class="btn secondary" data-filter="All">Browse subjects</button></div>`}`}
function subjectDetail(){let item=subject(state.subject),count=questionBank.filter(q=>q.subject===item.id).length;return `${title(item.name,'SUBJECT OVERVIEW','reviewer')}<div class="glass pad"><strong>${item.topics.length} topic areas</strong><p class="small muted">${count} imported questions</p></div>${count?`<button class="action-row" data-go="question-library">${glyph('▧','cyan')}<span class="grow"><strong>Browse source questions</strong><small>${count} questions with answer keys and page references</small></span><span class="chev">›</span></button>`:''}<div class="chips">${['Lessons','Formulas','Solved Examples','Flashcards','Resources'].map(t=>`<button class="pill ${state.lessonTab===t?'active':''}" data-tab="${t}">${t}</button>`).join('')}</div>${state.lessonTab==='Resources'?sources():item.topics.map(t=>`<button class="action-row" data-topic="${esc(t)}"><span class="grow"><strong>${esc(t)}</strong><small>${esc(state.lessonTab)} · Open overview</small></span><span class="chev">›</span></button>`).join('')}`}
function questionLibrary(){let all=questionBank.filter(q=>q.subject===state.subject),topics=[...new Set(all.map(q=>q.topic))],qs=all.filter(q=>state.reviewTopic==='All'||q.topic===state.reviewTopic),i=Math.min(state.reviewIndex,qs.length-1),q=qs[i];return `${title('Question bank',subject(state.subject).name,'subject')}<div class="chips">${['All',...topics].map(t=>`<button class="pill ${state.reviewTopic===t?'active':''}" data-review-topic="${esc(t)}">${esc(t)}</button>`).join('')}</div>${q?`<div class="row between"><span class="small muted">Question ${i+1} of ${qs.length} · ${esc(q.type)}</span><button class="link-button" data-action="bookmark-review">${state.bookmarks.includes(q.id)?'★ Saved':'☆ Bookmark'}</button></div><div class="glass pad" style="margin-top:12px"><span class="tag">${esc(q.section)} · #${q.number}</span><h2>${esc(q.prompt)}</h2>${q.choices.map((c,j)=>`<div class="choice"><span class="choice-letter">${'ABCD'[j]}</span><span>${esc(c)}</span></div>`).join('')}<div class="softline"></div><button class="btn secondary wide" data-action="reveal-review">${state.reviewReveal?'Hide answer':'Show answer'}</button>${state.reviewReveal?`<p><strong>Answer: ${'ABCD'[q.answer]} · ${esc(q.choices[q.answer])}</strong></p><p class="small muted">Answer basis: ${esc(q.answerSource)}</p>${q.sourceNote?`<div class="notice">Source note: ${esc(q.sourceNote)}</div>`:''}${q.quality==='held'?'<div class="notice">Held from scored quizzes until the printed inconsistency is resolved.</div>':''}`:''}</div><p class="small muted">${esc(sourceRegistry.find(x=>x.id===q.sourceId).title)} · PDF page ${esc(q.pdfPages?.join('–')||q.pdfPage)}</p><div class="row"><button class="btn secondary grow" data-review-nav="prev" ${i===0?'disabled':''}>← Previous</button><button class="btn grow" data-review-nav="next" ${i===qs.length-1?'disabled':''}>Next →</button></div>`:'<div class="glass empty">No imported questions in this topic.</div>'}`}

function lesson(){let s=subject(state.subject),topic=state.topic||s.topics[0],key=`${s.id}::${topic}`,saved=state.lessonBookmarks.some(item=>item.key===key);return `${title(topic,s.name,'subject')}<div class="glass pad stack"><div class="eyebrow">${esc(state.lessonTab.toUpperCase())}</div><h2>Learning space</h2><p class="muted">This topic is ready for verified lessons, formulas, worked examples, flashcards and approved references. Imported source questions are available in the subject question bank. Full lessons and worked examples will be added in later batches.</p><div class="notice">Question records show their source page and answer basis; lesson text is still being developed.</div><div class="row"><button class="btn" data-go="practice">Practice source quiz</button><button class="btn secondary" data-action="save-lesson">${saved?'★ Saved':'☆ Bookmark'}</button></div></div>`}
function sources(){return `<div class="stack">${sourceRegistry.map(x=>`<div class="glass pad"><div class="row between"><span class="tag">${esc(x.kind)}</span><span class="small muted">${x.pages} pages</span></div><h3 style="margin:13px 0 5px">${esc(x.title)}</h3><p class="small muted" style="margin:0">${esc(x.status)}</p></div>`).join('')}</div>`}
function quizHome(){return `${title('Quiz','PRACTICE WITH PURPOSE')}${state.session?`<button class="action-row" data-go="active-quiz">${glyph('↻','cyan')}<span class="grow"><strong>Resume ${esc(state.session.category)}</strong><small>Question ${state.session.index+1} of ${state.session.ids.length}</small></span><span class="chev">›</span></button>`:''}<div class="glass hero"><div class="eyebrow">READY TO PRACTICE?</div><h2>${playableQuestions.length} imported questions are ready.</h2><p class="muted small">Choose a source or subject and review the key after you finish.</p><button class="btn" data-go="quiz-setup">Create a quiz →</button></div><div class="section-head"><h2>Explore quizzes</h2></div>${[['Topic Quiz','Practice by subject'],['Mock Exam','Mix initial sources'],['Previous Exams','Start with Chemistry Exam 1'],['Custom Quiz','Choose your settings'],['Results & History','Review your last attempt'],['Bookmarks','Saved questions']].map(([name,desc])=>`<button class="action-row" data-quiz-category="${name}">${glyph('▣','blue')}<span class="grow"><strong>${name}</strong><small>${desc}</small></span><span class="chev">›</span></button>`).join('')}<div class="notice">One book question is held from scored quizzes because its worked solution and printed choices differ.</div>`}

function quizSetup(){let s=state.quizSetup,availableSubjects=subjects.filter(x=>playableQuestions.some(q=>q.subject===x.id)),selected=normalizeSelectedSubjects(s.subjects??s.subject,availableSubjects.map(x=>x.id));s.subjects=selected;delete s.subject;let matches=filterQuizQuestions(playableQuestions,s),allSelected=selected.length===availableSubjects.length;let countFor=id=>playableQuestions.filter(q=>q.subject===id&&(s.source==='all'||q.sourceId===s.source)&&(s.type==='All'||q.type===s.type)).length;return `${title(state.quizCategory,'QUIZ SETUP','quiz')}<div class="glass pad"><fieldset class="subject-picker"><legend>Subjects</legend><button type="button" class="subject-option all ${allSelected?'selected':''}" data-quiz-subject="all" aria-pressed="${allSelected}"><span><strong>All available subjects</strong><small>${playableQuestions.filter(q=>(s.source==='all'||q.sourceId===s.source)&&(s.type==='All'||q.type===s.type)).length} questions with current filters</small></span><span class="subject-check">${allSelected?'✓':'＋'}</span></button><div class="subject-option-grid">${availableSubjects.map(x=>{let active=selected.includes(x.id);return `<button type="button" class="subject-option ${active?'selected':''}" data-quiz-subject="${x.id}" aria-pressed="${active}"><span><strong>${esc(x.name)}</strong><small>${countFor(x.id)} available</small></span><span class="subject-check">${active?'✓':'＋'}</span></button>`}).join('')}</div></fieldset><div class="notice quiz-availability"><strong>${selected.length} subject${selected.length===1?'':'s'} selected · ${matches.length} matching questions</strong><span>${selected.map(id=>esc(subject(id).name)).join(' · ')}</span></div><label class="field">Source<select id="quiz-source"><option value="all">All initial sources</option>${sourceRegistry.map(x=>`<option value="${x.id}" ${s.source===x.id?'selected':''}>${esc(x.title)}</option>`).join('')}</select></label><label class="field">Question type<select id="quiz-type">${['All','Terminology','Solving'].map(x=>`<option ${s.type===x?'selected':''}>${x}</option>`).join('')}</select></label><label class="field">Number of questions<select id="quiz-count">${[5,10,20,40,80,100].map(n=>`<option value="${n}" ${s.count===n?'selected':''}>Up to ${n}</option>`).join('')}</select></label><div class="switch-row"><div><strong>Practice mode</strong><div class="small muted">Show correct and incorrect answers immediately</div></div><button class="toggle ${s.practice?'on':''}" data-action="practice-toggle" aria-label="Toggle practice mode"></button></div><div class="switch-row"><div><strong>Timer</strong></div><button class="toggle ${s.timer?'on':''}" data-action="timer-toggle" aria-label="Toggle timer"></button></div><div class="switch-row"><div><strong>Randomize questions</strong></div><button class="toggle ${s.random?'on':''}" data-action="random-toggle" aria-label="Toggle question order"></button></div><div class="switch-row"><div><strong>Shuffle choices</strong><div class="small muted">Off by default for source exams</div></div><button class="toggle ${s.shuffleChoices?'on':''}" data-action="choice-shuffle-toggle" aria-label="Toggle choice shuffle"></button></div><button class="btn wide" data-action="start-quiz" ${matches.length?'':'disabled'}>Start ${esc(state.quizCategory)} →</button><p class="footnote">Questions are drawn only from the selected subjects. A single selected subject works exactly like the original flow.</p></div>`}

function activeQuiz(){let ss=state.session;if(!ss)return quizHome();let q=questionBank.find(x=>x.id===ss.ids[ss.index]);if(!q)return `${title('Quiz unavailable','SOURCE QUESTION CHANGED','quiz')}<div class="notice">Start a new quiz.</div>`;let n=ss.index+1,chosen=ss.answers[q.id],revealed=ss.practice&&chosen!==undefined;return `<div class="quiz-head"><button class="icon-btn" data-action="exit-quiz">×</button><div class="brand">${esc(ss.category)}</div><span class="pill" data-clock>${ss.timer?formatElapsed(Date.now()-ss.startedAt):ss.practice?'Practice mode':'No timer'}</span></div><div class="row between"><span class="small muted">Question ${n} of ${ss.ids.length} · ${esc(q.type)}</span><button class="link-button" data-action="bookmark-question">${state.bookmarks.includes(q.id)?'★ Saved':'☆ Bookmark'}</button></div><div class="meter" style="margin:11px 0 22px"><i style="width:${n/ss.ids.length*100}%"></i></div><div class="glass question-card"><span class="tag">${esc(subject(q.subject).name)} · ${esc(q.topic)}</span><h2 style="margin:17px 0 20px">${esc(q.prompt)}</h2>${(ss.choiceOrders?.[q.id]||[0,1,2,3]).map((original,i)=>{let feedback=practiceChoiceState(original,chosen,q.answer,ss.practice);return `<button class="choice ${feedback}" data-answer="${original}" ${revealed?'disabled':''}><span class="choice-letter">${'ABCD'[i]}</span><span>${esc(q.choices[original])}</span></button>`}).join('')}${revealed?`<div class="answer-feedback ${chosen===q.answer?'correct':'incorrect'}"><strong>${chosen===q.answer?'Correct!':'Not quite. The correct answer is highlighted in green.'}</strong>${q.explanation?`<span>${esc(q.explanation)}</span>`:''}${q.formula?`<span>Formula: ${esc(q.formula)}</span>`:''}</div>`:''}</div><div class="sticky-actions"><button class="btn secondary" data-action="prev" ${ss.index===0?'disabled':''}>← Previous</button><button class="btn" data-action="${n===ss.ids.length?'finish':'next'}">${n===ss.ids.length?'Finish quiz':'Next →'}</button></div><div class="row between" style="margin-top:14px"><span class="small muted">${ss.practice?'Practice feedback is saved with your answer.':'Answers saved on this device.'}</span><button class="pill" data-action="calc-overlay">∑ Calculator</button></div>`}

function results(){let r=state.lastResult;if(!r)return `${title('Results','QUIZ HISTORY','quiz')}<div class="glass empty">No completed quiz yet.</div>`;let attemptTopics=r.topicStats||{},attemptSubjects=r.subjectStats||{};return `${title('Your results','PRACTICE COMPLETE','quiz')}<div class="glass hero" style="text-align:center"><div class="eyebrow">YOUR SCORE</div><h1 style="font-size:3.5rem;margin:0">${r.correct}/${r.total}</h1><p class="muted">${Math.round(r.correct/r.total*100)}% correct · ${r.seconds}s elapsed</p></div><div class="section-head"><h2>Subject performance</h2></div><div class="result-breakdown">${Object.entries(attemptSubjects).map(([id,v])=>`<div class="glass pad small"><strong>${esc(subject(id).name)}</strong><span>${v.correct}/${v.attempts} correct · ${Math.round(v.correct/v.attempts*100)}%</span></div>`).join('')||'<p class="small muted">Subject details are available after your next quiz.</p>'}</div><div class="section-head"><h2>Topic performance</h2></div><div class="result-breakdown">${Object.entries(attemptTopics).sort((a,b)=>a[0].localeCompare(b[0])).map(([topic,v])=>`<div class="glass pad small"><strong>${esc(topic.split(' / ').slice(1).join(' / ')||topic)}</strong><span>${v.correct}/${v.attempts} correct · ${Math.round(v.correct/v.attempts*100)}%</span></div>`).join('')||'<p class="small muted">Topic details are available after your next quiz.</p>'}</div><div class="section-head"><h2>Topics to revisit</h2></div>${Object.entries(attemptTopics).filter(([,v])=>v.correct<v.attempts).sort((a,b)=>a[1].correct/a[1].attempts-b[1].correct/b[1].attempts).slice(0,3).map(([topic,v])=>`<div class="glass pad small" style="margin-bottom:8px">${esc(topic)} · ${v.correct}/${v.attempts} correct</div>`).join('')||'<p class="small muted">No missed topics in this attempt.</p>'}<div class="section-head"><h2>Answer review</h2></div>${r.ids.map((id,i)=>{let q=questionBank.find(x=>x.id===id),a=r.answers[id],order=r.choiceOrders?.[id]||[0,1,2,3];if(!q)return '';return `<div class="glass pad" style="margin-bottom:10px"><div class="row between"><span class="small muted">Question ${i+1} · ${esc(q.section)} #${q.number}</span>${badge(a===q.answer?'Correct':'Review')}</div><h3>${esc(q.prompt)}</h3><p class="small">Your answer: <strong>${a===undefined?'Unanswered':`${displayedAnswerLetter(order,a)} · ${esc(q.choices[a])}`}</strong><br>Correct answer: <strong>${displayedAnswerLetter(order,q.answer)} · ${esc(q.choices[q.answer])}</strong></p><p class="small muted">Answer basis: ${esc(q.answerSource)}</p>${q.sourceNote?`<div class="notice">Source note: ${esc(q.sourceNote)}</div>`:''}<p class="small muted">${esc(sourceRegistry.find(x=>x.id===q.sourceId).title)} · PDF page ${esc(q.pdfPages?.join('–')||q.pdfPage)}</p></div>`}).join('')}<button class="btn wide" data-go="quiz-setup">Try another quiz</button>`}

function noteRow(n){return `<div class="action-row"><button class="note-row-main grow" data-edit-note="${n.id}">${glyph(n.formula?'∑':'▤',n.formula?'cyan':'amber')}<span class="grow"><strong>${esc(n.title||'Untitled note')}</strong><small>${esc(n.folder||'General')} · ${esc((n.body||n.formula||'').slice(0,42))}</small></span></button><button class="icon-btn note-pin" data-note-pin="${n.id}" title="${n.pinned?'Unpin':'Pin'} note" aria-label="${n.pinned?'Unpin':'Pin'} note">${n.pinned?'★':'☆'}</button></div>`}
function notes(){let folders=['General','Reviewer','Formulas','Quiz Mistakes'],list=state.notes.filter(n=>!state.search||`${n.title} ${n.body} ${n.formula||''}`.toLowerCase().includes(state.search.toLowerCase()));if(state.noteFilter==='Pinned')list=list.filter(n=>n.pinned);if(state.noteFilter==='Formulas')list=list.filter(n=>n.formula);return `${title('My Notes','YOUR LEARNING SPACE')}<div class="glass hero note-hero"><div class="eyebrow">CAPTURE YOUR THINKING</div><h2>Your notes. A smarter way to learn.</h2><p class="small muted">Keep formulas, thoughts and quiz takeaways together.</p><div class="row"><span class="pill">${state.notes.length} notes</span><span class="pill">${state.notes.filter(n=>n.pinned).length} pinned</span></div></div><label class="search"><span>⌕</span><input aria-label="Search notes" placeholder="Search your notes" data-search="notes" value="${esc(state.search)}"></label><button class="btn wide" data-action="new-note">＋ Create a note</button><div class="section-head"><h2>Quick access</h2></div><div class="grid2">${tile('▣','Folders','Organize by topic','note-folders','blue')}${tile('∑','Formulas','Saved equations','formulas','violet')}${tile('☆','Bookmarks','Saved questions','bookmarks','cyan')}${tile('★','Pinned notes','Important ideas','note-pinned','amber')}</div><div class="section-head"><h2>Recent notes</h2><span class="small muted">${list.length} shown</span></div><div class="chips">${['All','Pinned','Formulas'].map(f=>`<button class="pill ${state.noteFilter===f?'active':''}" data-note-filter="${f}">${f}</button>`).join('')}</div>${list.map(noteRow).join('')||`<div class="glass empty">${glyph('✎','amber')}<h3>Your ideas start here</h3><p>Capture a formula, concept or reminder.</p></div>`}`}
function noteFolders(){let folders=['General','Reviewer','Formulas','Quiz Mistakes'];return `${title('Folders','ORGANIZE YOUR NOTES','notes')}${folders.map((f,i)=>`<button class="action-row" data-note-folder="${esc(f)}">${glyph(['▤','▥','∑','▣'][i],['blue','green','violet','coral'][i])}<span class="grow"><strong>${f}</strong><small>${state.notes.filter(n=>n.folder===f).length} notes</small></span><span class="chev">›</span></button>`).join('')}`}
function noteFolder(){let list=state.notes.filter(n=>n.folder===state.selectedFolder);return `${title(state.selectedFolder,'NOTES FOLDER','note-folders')}${list.map(noteRow).join('')||'<div class="glass empty">No notes in this folder yet.</div>'}<button class="btn wide" data-action="new-note">＋ Add a note</button>`}
function noteEdit(){let n=state.notes.find(x=>x.id===state.editNote)||{title:'',body:'',folder:state.selectedFolder||'General',formula:'',pinned:false};return `${title(n.id?'Edit note':'New note','WRITE & REMEMBER','notes')}<form id="note-form" class="glass pad"><label class="field">Title<input name="title" maxlength="100" placeholder="e.g. Ohm’s Law" value="${esc(n.title)}" required></label><label class="field">Folder<select name="folder">${['General','Reviewer','Formulas','Quiz Mistakes'].map(x=>`<option ${n.folder===x?'selected':''}>${x}</option>`).join('')}</select></label><label class="field">Formula (optional)<input name="formula" placeholder="e.g. V = IR" value="${esc(n.formula||'')}"></label><label class="field">Your notes<textarea name="body" placeholder="Write your thoughts here...">${esc(n.body)}</textarea></label><div class="note-editor-tools"><button class="pill" type="button" data-insert="Σ">Σ Symbol</button><button class="pill" type="button" data-insert="∫">∫ Integral</button><button class="pill" type="button" data-insert="√">√ Root</button><button class="pill" type="button" data-insert="Ω">Ω Ohm</button></div><label class="switch-row"><span>Pin this note</span><input type="checkbox" name="pinned" ${n.pinned?'checked':''}></label><div class="softline"></div><div class="row"><button class="btn grow" type="submit">Save note</button>${n.id?'<button class="btn secondary" type="button" data-action="delete-note">Delete</button>':''}</div></form>`}
function more(){let items=[['calculator','∑','Calculator','Scientific tools','green'],['scanner','▤','Scan & extract','On-device text recognition','cyan'],['profile','♙','Profile','Your account','blue'],['settings','⚙','Settings','Preferences & theme','violet'],['help','?','Help & FAQs','Get answers','cyan'],['support','♡','Owner & Support','Send feedback or resources','coral'],['sources','▧','Source library','Registered materials','cyan'],['about','ⓘ','About','About ESAS Reviewer','amber']];if(!window.NativeBridge)items.splice(3,0,['download-app','⇩','Download Android app',publicConfig.apkVersion,'green']);return `${title('More','TOOLS & SETTINGS')}${items.map(([id,icon,label,desc,color])=>`<button class="action-row" data-go="${id}">${glyph(icon,color)}<span class="grow"><strong>${label}</strong><small>${desc}</small></span><span class="chev">›</span></button>`).join('')}${ownerPreview()?`<button class="action-row" data-go="admin">${glyph('✦','violet')}<span class="grow"><strong>Owner dashboard</strong><small>Review resource submissions</small></span><span class="chev">›</span></button>`:''}<button class="action-row" data-action="signout">${glyph('↪','blue')}<span class="grow"><strong>Sign out</strong><small>Return to welcome screen</small></span></button>`}
function welcome(){return `<div class="welcome"><div class="topbar"><div class="brand"><span class="brand-mark">${brandSymbol}</span> ESAS Reviewer</div><button class="icon-btn" data-action="theme" aria-label="Switch theme">${state.theme==='light'?'☾':'☀'}</button></div><div class="welcome-art"><img class="brand-wordmark" src="./assets/brand/logo-horizontal.png" alt="ESAS Reviewer — Engineering Sciences and Allied Subjects"></div><div class="glass onboarding-card"><div class="eyebrow">STUDY SMARTER · GROW STRONGER</div><h1>Your review space, beautifully focused.</h1><p>Lessons, quizzes, notes and tools in one place.</p><div class="stack"><button class="btn wide" data-go="login">Get started →</button><button class="btn secondary wide" data-action="guest">Continue as guest</button>${!window.NativeBridge?'<button class="btn secondary wide" data-go="download-app">Download Android app</button>':''}</div></div><p class="footnote" style="text-align:center">Offline study is available. Sign in for account features.</p></div>`}
function downloadApp(){return `${title('Download Android app','OFFICIAL APK','more')}<div class="glass hero" style="text-align:center"><img src="./assets/brand/app-icon.png" alt="ESAS Reviewer app icon" style="width:96px;height:96px;border-radius:24px"><h2>ESAS Reviewer for Android</h2><p class="muted">${esc(publicConfig.apkVersion)} · ${esc(publicConfig.minimumAndroid)}</p><a class="btn wide" href="${esc(publicConfig.apkDownloadUrl)}" download="ESAS-Reviewer.apk">Download APK</a><p class="footnote">Your phone may ask you to allow installation from this browser. Only install APK files downloaded from this official page.</p></div>`}
function login(mode='login'){return `${title(mode==='register'?'Create account':mode==='forgot'?'Reset password':'Welcome back','ACCOUNT','welcome')}<div class="glass pad"><div class="notice">Sign in with your ESAS Reviewer account. Guest use remains available offline.</div><form id="login-form" style="margin-top:18px">${mode==='register'?'<label class="field">Name<input name="name" autocomplete="name" required placeholder="Your name"></label>':''}<label class="field">Email<input name="email" type="email" autocomplete="email" required placeholder="you@example.com"></label>${mode!=='forgot'?'<label class="field">Password<input name="password" type="password" autocomplete="current-password" required placeholder="Enter your password"></label>':''}<button class="btn wide" type="submit">${mode==='forgot'?'Send reset email':mode==='register'?'Continue':'Continue'}</button></form>${mode==='login'?'<div class="row between" style="margin-top:16px"><button class="link-button" data-go="register">Create account</button><button class="link-button" data-go="forgot">Forgot password?</button></div><div class="softline"></div><button class="btn secondary wide" data-action="guest">Continue as guest</button><p class="footnote">Email and password sign-in uses Firebase. Google sign-in is not configured.</p>':mode==='register'?'<button class="link-button" data-go="login">Already have an account?</button>':'<button class="link-button" data-go="login">Back to sign in</button>'}</div>`}
function profile(){return `${title('Profile','ACCOUNT','more')}<div class="glass pad"><div class="row"> <span class="avatar" style="width:56px;height:56px;font-size:1.3rem">${esc(state.profile.name.charAt(0))}</span><div><h2 style="margin:0">${esc(state.profile.name)}</h2><span class="small muted">${ownerPreview()?'Verified owner':'Learner'}</span></div></div><div class="softline"></div><p class="small muted">Account access uses Firebase when signed in. Guest study data remains on this device.</p>${ownerEligible()?'<button class="btn secondary wide" data-go="admin">Open owner dashboard</button>':''}</div>`}
function settings(){return `${title('Settings','PERSONALIZE YOUR SPACE','more')}<div class="glass pad"><h3>Appearance</h3><div class="switch-row"><div><strong>${state.theme==='light'?'Theme C · Liquid Glass Light':'Theme D · Liquid Glass Dark'}</strong><div class="small muted">Switch between approved themes</div></div><button class="toggle ${state.theme==='dark'?'on':''}" data-action="theme" aria-label="Toggle dark theme"></button></div></div><div class="glass pad" style="margin-top:13px"><h3>Data & privacy</h3><p class="small muted">Notes and practice stay on this device; signed-in resource submissions use Firestore. It does not sync across devices.</p></div>`}
function support(){return `${title('Owner & Support','HELP IMPROVE ESAS','more')}<div class="glass hero"><h2>Built for learners, with learners.</h2><p class="small muted">Share an idea, request content or suggest a resource for review.</p></div><div class="section-head"><h2>Submit a resource</h2></div><form id="submission-form" class="glass pad"><label class="field">Resource title<input name="title" required maxlength="100" placeholder="e.g. DC Machines formula guide"></label><label class="field">Category<select name="category"><option>Reviewer</option><option>Quiz</option><option>Notes</option><option>Other</option></select></label><label class="field">Description<textarea name="detail" required placeholder="Describe the content and its source"></textarea></label><label class="field">File name (no attachment)<input name="fileName" type="text" placeholder="Optional: resource.pdf"></label><button class="btn wide" type="submit">Submit for review</button><p class="footnote">The description is submitted for review when signed in. File bytes are not uploaded. Nothing publishes automatically.</p></form><div class="section-head"><h2>Submission status</h2></div>${state.submissions.filter(x=>x.id!=='sample-1').map(x=>`<div class="glass pad row between" style="margin-bottom:8px"><div><strong>${esc(x.title)}</strong><div class="small muted">${esc(x.category)}</div></div>${badge(x.status)}</div>`).join('')||'<p class="small muted">Your submissions will appear here.</p>'}${state.supportEnabled?'<div class="glass pad" style="margin-top:18px;text-align:center"><h3>Voluntary support</h3><p class="small muted">If you wish to support the reviewer project, you can use the owner’s approved GCash QR.</p><img src="./assets/gcash-owner-qr.jpg" alt="Owner GCash support QR" style="width:min(100%,210px);border-radius:15px;display:block;margin:0 auto"><p class="footnote">Optional support. Transfer fees may apply.</p></div>':''}`}
function jsonlImportPanel(){let d=state.importDraft;return `<div class="section-head"><h2>Question import</h2><span class="small muted">${state.publishedCount} owner-published</span></div><div class="glass pad import-panel">${d?`<div class="row between"><div><strong>${d.count} imported for review</strong><div class="small muted">${d.ready||0} draft-ready · ${d.held||0} needs review · ${d.duplicates||0} duplicates skipped</div></div>${badge('Draft')}</div><div class="notice">No upload is published automatically. Open every record to review its prompt, choices, answer, source, and status.</div><button class="btn wide" data-go="content-manager">Review imported questions →</button>`:`<p class="small muted">Choose a JSONL file to validate and place it in the local review queue. Publishing is available only inside each question’s full review form.</p><button class="btn secondary wide" data-native="pickJsonl">Choose and validate JSONL</button>`}</div>`}
function admin(){if(!ownerPreview())return profile();let list=state.submissions.filter(x=>state.adminFilter==='All'||x.status===state.adminFilter);return `${title('Owner dashboard','VERIFIED OWNER','more')}<div class="notice">You are signed in as the verified owner. Imported questions stay unpublished until you review and publish each record in Content Manager.</div>${jsonlImportPanel()}<div class="stat-row" style="margin:16px 0">${['Pending','Approved','Rejected'].map(t=>`<div class="glass stat"><strong>${state.submissions.filter(s=>s.status===t).length}</strong><span class="small">${t}</span></div>`).join('')}</div><div class="section-head"><h2>Resource submissions</h2></div><div class="chips">${['All','Pending','Approved','Rejected'].map(f=>`<button class="pill ${f===state.adminFilter?'active':''}" data-admin-filter="${f}">${f}</button>`).join('')}</div>${list.map(x=>`<button class="action-row" data-submission="${x.id}">${glyph('▧','cyan')}<span class="grow"><strong>${esc(x.title)}</strong><small>${esc(x.submittedBy)} · ${esc(x.category)}</small></span>${badge(x.status)}</button>`).join('')||'<div class="glass empty">No submissions in this view.</div>'}<div class="section-head"><h2>Owner tools</h2></div><button class="action-row" data-go="content-manager">${glyph('⚙','violet')}<span class="grow"><strong>Content Manager</strong><small>Search, review, edit and publish local questions</small></span><span class="chev">›</span></button>${[['User Management','Accounts and roles'],['Messages & Suggestions','Learner feedback'],['GCash Support Settings','Optional support visibility']].map(([a,b])=>`<button class="action-row" data-admin-tool="${esc(a)}">${glyph('⚙','violet')}<span class="grow"><strong>${a}</strong><small>${b}</small></span><span class="chev">›</span></button>`).join('')}`}
function contentManager(){if(!ownerPreview())return profile();let counts=Object.fromEntries(CONTENT_STATUSES.map(status=>[status,state.contentItems.filter(item=>item.status===status).length])),folders=managedFolders(state.contentItems),list=filterManagedQuestions(state.contentItems,{status:state.contentFilter,folder:state.contentFolder,search:state.contentSearch});return `${title('Content Manager','LOCAL OWNER CONTENT','admin')}<div class="notice">Only <strong>Published</strong> questions with a confirmed correct answer enter scored quizzes. Needs Review, Draft, and Rejected records remain review-only.</div><div class="content-stats">${CONTENT_STATUSES.map(status=>`<div class="glass stat"><strong>${counts[status]}</strong><span class="small">${status}</span></div>`).join('')}</div><div class="row content-actions"><button class="btn grow" data-action="new-content">＋ Add question</button><button class="btn secondary" data-native="pickJsonl">Import JSONL</button></div><div class="section-head"><h2>JSON upload folders</h2><span class="small muted">${folders.length} folders</span></div><div class="upload-folders"><button class="upload-folder ${state.contentFolder==='All uploads'?'active':''}" data-content-folder="All uploads"><span>▧</span><strong>All uploads</strong><small>${state.contentItems.length} questions</small></button>${folders.map(folder=>`<button class="upload-folder ${state.contentFolder===folder.name?'active':''}" data-content-folder="${esc(folder.name)}"><span>▧</span><strong>${esc(folder.name)}</strong><small>${folder.count} questions</small></button>`).join('')}</div><label class="search"><span>⌕</span><input aria-label="Search owner questions" placeholder="Search ID, prompt, subject, topic or source" data-content-search value="${esc(state.contentSearch)}"></label><div class="chips">${['All',...CONTENT_STATUSES].map(status=>`<button class="pill ${state.contentFilter===status?'active':''}" data-content-filter="${status}">${status}${status==='All'?` (${list.length})`:` (${counts[status]})`}</button>`).join('')}</div><div class="content-list">${list.map(item=>`<button class="action-row content-row" data-content-id="${esc(item.id)}"><span class="grow"><strong>${esc(item.prompt||'Untitled question')}</strong><small>${esc(item.id)} · ${esc(item.subjectName||item.subject)} · ${esc(item.topic||'No topic')} · ${esc(item.importFolder||item.sourceFile||'Manual entries')}</small></span>${badge(item.status)}</button>`).join('')||'<div class="glass empty">No questions match this folder and status.</div>'}</div>`}
function contentEditor(){if(!ownerPreview())return profile();let existing=state.contentItems.find(item=>item.id===state.contentEditId),q=existing||{...blankManagedQuestion(),id:`owner-${Date.now()}`},subjectNames=[...new Set(subjects.map(item=>item.name).concat(state.contentItems.map(item=>item.subjectName).filter(Boolean)))].sort(),topics=[...new Set(subjects.flatMap(item=>item.topics).concat(state.contentItems.map(item=>item.topic).filter(Boolean)))].sort();return `${title(existing?'Review question':'Add question','CONTENT MANAGER','content-manager')}<form id="content-form" class="glass pad content-form" data-original-id="${esc(existing?.id||'')}"><div class="row between"><span class="small muted">${existing?'Review every important field before publishing.':'Create a local owner question.'}</span>${badge(q.status||'Draft')}</div><label class="field">Question ID<input name="id" required value="${esc(q.id)}" autocomplete="off"></label><label class="field">Question prompt<textarea name="prompt" required>${esc(q.prompt)}</textarea></label><fieldset class="choice-editor"><legend>Four choices <span class="small muted">(intentional blanks are allowed)</span></legend>${[0,1,2,3].map(index=>`<label class="field"><span>Choice ${'ABCD'[index]}</span><input name="choice${index}" value="${esc(q.choices?.[index]??'')}" placeholder="Leave blank only when the source choice is blank"></label>`).join('')}</fieldset><label class="field">Correct answer<select name="answer"><option value="">Unconfirmed</option>${[0,1,2,3].map(index=>`<option value="${index}" ${q.answer===index?'selected':''}>${'ABCD'[index]}</option>`).join('')}</select></label><label class="field">Explanation<textarea name="explanation">${esc(q.explanation||'')}</textarea></label><label class="field">Formula<input name="formula" value="${esc(q.formula||'')}" placeholder="Optional formula"></label><label class="field">Subject<input name="subjectName" list="content-subjects" required value="${esc(q.subjectName||'')}" placeholder="Select or create a subject"><datalist id="content-subjects">${subjectNames.map(name=>`<option value="${esc(name)}"></option>`).join('')}</datalist></label><label class="field">Topic<input name="topic" list="content-topics" required value="${esc(q.topic||'')}" placeholder="Select or create a topic"><datalist id="content-topics">${topics.map(topic=>`<option value="${esc(topic)}"></option>`).join('')}</datalist></label><label class="field">Type<select name="type">${['Terminology','Solving'].map(type=>`<option ${q.type===type?'selected':''}>${type}</option>`).join('')}</select></label><label class="field">Source<input name="sourceFile" value="${esc(q.sourceFile||'')}" placeholder="Book, exam, or file name"></label><label class="field">JSON upload folder<input name="importFolder" value="${esc(q.importFolder||'Manual entries')}" readonly></label><div class="form-grid"><label class="field">Source page<input name="pdfPage" type="number" min="0" value="${esc(q.pdfPage||0)}"></label><label class="field">Question number<input name="number" type="number" min="1" value="${esc(q.number||1)}"></label></div><label class="field">Section<input name="section" value="${esc(q.section||'Owner content')}"></label><label class="field">Answer/source note<textarea name="sourceNote">${esc(q.sourceNote||'')}</textarea></label><input type="hidden" name="sourceId" value="${esc(q.sourceId||'owner-import')}"><div class="content-save-actions"><button class="btn secondary" type="submit" name="submitStatus" value="Draft">Save draft</button><button class="btn secondary" type="submit" name="submitStatus" value="Needs Review">Needs review</button><button class="btn" type="submit" name="submitStatus" value="Published">Publish</button><button class="btn danger" type="submit" name="submitStatus" value="Rejected">Reject</button></div><p class="footnote">Publishing is explicit. There is no automatic or bulk publication in this version.</p></form>`}
function submissionDetail(){if(!ownerPreview())return profile();let x=state.submissions.find(s=>s.id===state.submissionId);if(!x)return admin();return `${title('Submission','OWNER REVIEW','admin')}<div class="glass pad"><div class="row between"><span class="tag">${esc(x.category)}</span>${badge(x.status)}</div><h2 style="margin-top:17px">${esc(x.title)}</h2><p class="muted">${esc(x.detail)}</p><p class="small muted">Submitted by ${esc(x.submittedBy)}${x.fileName?' · Listed file: '+esc(x.fileName):''}</p><div class="notice">Only the description and listed filename are available here. Check source rights and content before any later publication.</div><div class="row" style="flex-wrap:wrap;margin-top:17px"><button class="btn" data-status="Approved">Approve</button><button class="btn secondary" data-status="Rejected">Reject</button><button class="btn secondary" data-status="Changes requested">Request changes</button></div></div>`}
function accessQuestionLibrary(){let qs=visibleQuestionBank().filter(q=>q.subject===state.subject),i=Math.max(0,Math.min(state.reviewIndex,qs.length-1)),q=qs[i];return `${title('Question bank',subject(state.subject).name,'subject')}${!fullAccess()?'<div class="notice">This is the free 20-question selection for this subject.</div>':''}${q?`<div class="row between"><span>Question ${i+1} of ${qs.length} · ${esc(q.type)}</span><button class="link-button" data-action="bookmark-review">☆ Bookmark</button></div><div class="glass pad"><h2>${esc(q.prompt)}</h2>${q.choices.map((c,j)=>`<div class="choice"><span class="choice-letter">${'ABCD'[j]}</span><span>${esc(c)}</span></div>`).join('')}<button class="btn secondary wide" data-action="reveal-review">${state.reviewReveal?'Hide answer':'Show answer'}</button>${state.reviewReveal?`<p><strong>Answer: ${'ABCD'[q.answer]} · ${esc(q.choices[q.answer])}</strong></p>`:''}</div><div class="row"><button class="btn secondary grow" data-review-nav="prev" ${i===0?'disabled':''}>← Previous</button><button class="btn grow" data-review-nav="next" ${i===qs.length-1?'disabled':''}>Next →</button></div>`:'<div class="glass empty">No available questions.</div>'}`}
function accountLogin(mode='login'){return `${title(mode==='register'?'Create account':mode==='forgot'?'Reset password':'Welcome back','ACCOUNT','welcome')}<div class="glass pad"><form id="login-form">${mode==='register'?'<label class="field">Name<input name="name" autocomplete="name" required></label>':''}<label class="field">Email<input name="email" type="email" autocomplete="email" required></label>${mode!=='forgot'?`<label class="field">Password<input name="password" type="password" minlength="6" autocomplete="${mode==='register'?'new-password':'current-password'}" required></label>`:''}${mode==='register'?'<label class="field">Confirm password<input name="confirmPassword" type="password" minlength="6" autocomplete="new-password" required></label>':''}<button class="btn wide" type="submit">${mode==='forgot'?'Send reset email':'Continue'}</button></form>${mode==='login'?'<div class="row between"><button class="link-button" data-go="register">Create account</button><button class="link-button" data-go="forgot">Forgot password?</button></div><p class="footnote">Android can offer to save your password securely after sign-in.</p>':`<button class="link-button" data-go="login">Back to sign in</button>`}</div>`}
function accountProfile(){let d=state.profileDetails,initial=(d.name||state.profile.name||'G').charAt(0).toUpperCase();return `${title('Profile','ACCOUNT','more')}<div class="glass pad profile-summary"><div class="row"><div class="profile-photo">${d.photoData?`<img src="${esc(d.photoData)}" alt="Profile photo">`:`<span>${esc(initial)}</span>`}</div><div class="grow"><h2 style="margin:0">${esc(d.name||state.profile.name)}</h2><span class="small muted">${ownerEligible()?'Verified owner':esc(accessLabel(state.accessUntil))}</span></div></div><button type="button" class="btn secondary wide" data-native="pickProfilePhoto" ${state.nativeUid?'':'disabled'}>Choose profile picture</button></div><form id="profile-form" class="glass pad profile-form"><h3>Edit profile information</h3><label class="field">Real name<input name="name" value="${esc(d.name||state.profile.name||'')}" maxlength="80" required></label><label class="field">Nickname<input name="nickname" value="${esc(d.nickname||'')}" maxlength="50"></label><div class="form-grid"><label class="field">Age<input name="age" type="number" min="13" max="120" value="${esc(d.age||'')}"></label><label class="field">Role / profession<input name="profession" value="${esc(d.profession||'Student')}" maxlength="60" placeholder="Student, professor, publisher"></label></div><label class="field">Address<input name="address" value="${esc(d.address||'')}" maxlength="180"></label><label class="field">Email address<input value="${esc(state.profile.email||'Guest account')}" readonly></label><label class="field">Phone number<input name="phone" inputmode="tel" value="${esc(d.phone||'')}" maxlength="30"></label><button class="btn wide" ${state.nativeUid?'':'disabled'}>Save profile</button><p class="footnote">Email changes remain protected by Firebase Authentication.</p></form>${ownerEligible()?`<button class="btn wide" data-action="toggle-owner">${ownerPreview()?'Switch to learner dashboard':'Switch to owner dashboard'}</button>`:''}${!ownerEligible()&&state.nativeUid?'<button class="btn secondary wide" data-go="support">Activate full access</button>':''}`}

function rankPage(){let history=get('quizHistory',[]),total=history.reduce((sum,x)=>sum+Number(x.total||0),0),correct=history.reduce((sum,x)=>sum+Number(x.correct||0),0),percent=total?Math.round(correct/total*100):0,personal=rankForPercent(percent),rows=state.leaderboard.length?state.leaderboard:[{uid:state.nativeUid||'local',name:state.profileDetails.name||state.profile.name||'Learner',bestPercent:percent,rank:personal,attempts:history.length}];return `${title('Rank & Leaderboard','PROGRESS RANKS','home')}<div class="glass hero rank-hero"><div class="eyebrow">YOUR CURRENT RANK</div><div class="rank-badge">${personal}</div><h2>${percent}% overall accuracy</h2><p class="small muted">Ranks progress from E, D, C, B, A, S, SS to SSS.</p></div><div class="section-head"><h2>Leaderboard</h2><span class="small muted">Best quiz score</span></div>${rows.map((row,index)=>`<div class="action-row leaderboard-row"><span class="leader-position">${index+1}</span><span class="grow"><strong>${esc(row.name||'Learner')}</strong><small>${Number(row.attempts||0)} attempt${Number(row.attempts||0)===1?'':'s'}</small></span><span class="rank-chip">${esc(row.rank||rankForPercent(Number(row.bestPercent||0)))}</span><strong>${Math.round(Number(row.bestPercent||0))}%</strong></div>`).join('')||'<div class="glass empty">Complete a quiz to enter the leaderboard.</div>'}`}
function paidQuizSetup(){let pool=availableQuestions(),s=state.quizSetup,availableSubjects=subjects.filter(x=>pool.some(q=>q.subject===x.id)),selected=normalizeSelectedSubjects(s.subjects??s.subject,availableSubjects.map(x=>x.id)),availableSources=sourceRegistry.filter(x=>pool.some(q=>q.sourceId===x.id)),selectedSources=normalizeSelectedSources(s.sources??s.source,availableSources.map(x=>x.id));s.subjects=selected;s.sources=selectedSources;delete s.subject;delete s.source;let matches=filterQuizQuestions(pool,s),sourceSet=new Set(selectedSources),countFor=id=>pool.filter(q=>q.subject===id&&sourceSet.has(q.sourceId)&&(s.type==='All'||q.type===s.type)).length,allSources=selectedSources.length===availableSources.length;return `${title(state.quizCategory,'QUIZ SETUP','quiz')}<div class="glass pad">${!fullAccess()?'<div class="notice">Free access includes up to 10 terminology and 10 solving questions per subject.</div>':''}<fieldset class="subject-picker"><legend>Subjects</legend><div class="subject-option-grid">${availableSubjects.map(x=>{let active=selected.includes(x.id);return `<button type="button" class="subject-option ${active?'selected':''}" data-quiz-subject="${x.id}"><span><strong>${esc(x.name)}</strong><small>${countFor(x.id)} available</small></span><span class="subject-check">${active?'✓':'＋'}</span></button>`}).join('')}</div></fieldset><fieldset class="subject-picker"><legend>Sources</legend><button type="button" class="subject-option all ${allSources?'selected':''}" data-quiz-source="all"><span><strong>All sources</strong><small>${pool.length} accessible questions</small></span><span class="subject-check">${allSources?'✓':'＋'}</span></button><div class="source-option-list">${availableSources.map(x=>{let active=selectedSources.includes(x.id),count=pool.filter(q=>q.sourceId===x.id).length;return `<button type="button" class="subject-option ${active?'selected':''}" data-quiz-source="${x.id}"><span><strong>${esc(x.title)}</strong><small>${count} available</small></span><span class="subject-check">${active?'✓':'＋'}</span></button>`}).join('')}</div></fieldset><div class="notice quiz-availability"><strong>${selected.length} subject${selected.length===1?'':'s'} · ${selectedSources.length} source${selectedSources.length===1?'':'s'} · ${matches.length} matching questions</strong></div><label class="field">Question type<select id="quiz-type">${['All','Terminology','Solving'].map(x=>`<option ${s.type===x?'selected':''}>${x}</option>`).join('')}</select></label><label class="field">Number<select id="quiz-count">${[5,10,20,40,80,100].map(n=>`<option value="${n}" ${s.count===n?'selected':''}>Up to ${n}</option>`).join('')}</select></label><div class="switch-row"><div><strong>Practice mode</strong><div class="small muted">Show correct and incorrect answers immediately</div></div><button class="toggle ${s.practice?'on':''}" data-action="practice-toggle" aria-label="Toggle practice mode"></button></div><button class="btn wide" data-action="start-quiz" ${matches.length?'':'disabled'}>Start quiz →</button></div>`}
function accessSupport(){let signed=!!state.nativeUid;return `${title('Access & Support','FULL ACCESS','more')}<div class="glass hero"><h2>${fullAccess()?'Full access is active.':'Unlock every question.'}</h2><p class="small muted">Every subject has 20 free questions. An approved GCash payment grants 30 days.</p></div>${state.supportEnabled?`<div class="glass pad" style="text-align:center"><h3>GCash · ₱${esc(state.config.monthlyPrice||99)} / 30 days</h3>${state.config.showGcashName&&state.config.gcashDisplayName?`<p>${esc(state.config.gcashDisplayName)}</p>`:''}<img src="${esc(state.config.gcashQrData)}" alt="GCash QR" style="width:min(100%,220px);border-radius:15px"><form id="payment-form"><label class="field">Reference number<input name="reference" required maxlength="80"></label><button class="btn wide" ${signed?'':'disabled'}>Submit payment for approval</button></form></div>`:''}<div class="section-head"><h2>Payment status</h2></div>${state.payments.map(p=>`<div class="glass pad row between"><span>${esc(p.reference)} · ${p.status==='Pending'?'Waiting for approval':p.status}</span>${badge(p.status)}</div>`).join('')||'<p class="small muted">No payment requests yet.</p>'}<div class="section-head"><h2>Activation code</h2></div><form id="activation-form" class="glass pad"><label class="field">One-time code<input name="code" required maxlength="40"></label><button class="btn wide" ${signed?'':'disabled'}>Activate</button></form><div class="section-head"><h2>Upload PDF</h2></div><form id="submission-form" class="glass pad"><label class="field">Title<input name="title" required maxlength="100"></label><label class="field">Category<select name="category"><option>Reviewer PDF</option><option>Suggestion</option><option>Other</option></select></label><label class="field">Description<textarea name="detail" required maxlength="4000"></textarea></label><button type="button" class="btn secondary wide" data-native="pickResourcePdf">${state.pickedResourceName?'Selected: '+esc(state.pickedResourceName):'Choose PDF'}</button><button class="btn wide" ${signed?'':'disabled'}>Upload for review</button><p class="footnote">Approval grants three days of full access once. Upload only material you may legally distribute.</p></form>${state.submissions.filter(x=>x.id!=='sample-1').map(x=>`<div class="glass pad"><div class="row between"><strong>${esc(x.title)}</strong>${badge(x.status)}</div>${x.reviewMessage?`<p>${esc(x.reviewMessage)}</p>`:''}${x.rewardGranted?'<p>Three-day access granted.</p>':''}</div>`).join('')}<div class="section-head"><h2>Message owner</h2></div><form id="message-form" class="glass pad"><label class="field">Type<select name="kind"><option>Message</option><option>Suggestion</option><option>Payment reference</option><option>Complaint</option></select></label><label class="field">Message<textarea name="body" required maxlength="2000"></textarea></label><button class="btn wide" ${signed?'':'disabled'}>Send</button></form>${state.messages.map(m=>`<div class="glass pad"><div class="row between"><strong>${esc(m.senderName)}</strong><span class="tag">${esc(m.kind||'Message')}</span></div><p>${esc(m.body)}</p></div>`).join('')}`}
function ownerDashboard(){if(!ownerPreview())return accountProfile();return `${title('Owner dashboard','VERIFIED OWNER','more')}<button class="btn secondary wide" data-action="toggle-owner">Switch to learner dashboard</button><div class="section-head"><h2>Pending PDFs</h2></div>${state.submissions.map(x=>`<button class="action-row" data-submission="${x.id}"><span class="grow"><strong>${esc(x.title)}</strong><small>${esc(x.submittedBy)}</small></span>${badge(x.status)}</button>`).join('')||'<div class="glass empty">No submissions.</div>'}<div class="section-head"><h2>Owner tools</h2></div>${[['content-manager','Content Manager'],['user-management','User Management'],['payment-management','GCash Payments'],['activation-codes','Activation Codes'],['owner-messages','Messages & Suggestions'],['app-settings','GCash & App Updates']].map(([id,label])=>`<button class="action-row" data-go="${id}"><strong class="grow">${label}</strong><span>›</span></button>`).join('')}`}
function ownerSubmission(){if(!ownerPreview())return accountProfile();let x=state.submissions.find(s=>s.id===state.submissionId);if(!x)return ownerDashboard();return `${title('Submission','OWNER REVIEW','admin')}<div class="glass pad"><h2>${esc(x.title)}</h2><p>${esc(x.detail)}</p><p class="small muted">${esc(x.submittedBy)} · ${esc(x.fileName)}</p>${x.storagePath?`<button class="btn secondary wide" data-download-submission="${x.id}">Download uploaded PDF</button>`:''}<label class="field">Review message<textarea id="review-message" maxlength="1000"></textarea></label><div class="row"><button class="btn" data-status="Approved">Approve + 3 days</button><button class="btn secondary" data-status="Rejected">Reject</button><button class="btn secondary" data-status="Changes requested">Request changes</button></div></div>`}
function userManagement(){let users=filterUsers(state.users,state.userSearch),active=state.users.filter(u=>u.uid===state.nativeUid||String(u.email||'').toLowerCase()===OWNER_PREVIEW_EMAIL||Number(u.accessUntil)>Date.now()).length;return `${title('User Management','OWNER','admin')}<div class="stat-row" style="margin:16px 0"><div class="glass stat"><strong>${state.users.length}</strong><span class="small">Accounts</span></div><div class="glass stat"><strong>${active}</strong><span class="small">Full access</span></div><div class="glass stat"><strong>${state.users.length-active}</strong><span class="small">Free access</span></div></div><label class="search"><span>⌕</span><input aria-label="Search users" placeholder="Search name, email or user ID" data-user-search value="${esc(state.userSearch)}"></label><div class="row" style="margin:12px 0"><button class="btn secondary" data-refresh-users>Refresh users</button></div><div class="user-list">${users.map(u=>{let protectedOwner=u.uid===state.nativeUid||String(u.email||'').toLowerCase()===OWNER_PREVIEW_EMAIL,online=Number(u.lastSeenAt)>Date.now()-300000,payment=state.payments.find(p=>p.uid===u.uid);return `<div class="glass pad user-card"><div class="row between"><div class="grow"><div class="row user-name-row"><strong>${esc(u.name||u.email||'Unnamed user')}</strong><span class="presence ${online?'online':''}">${online?'Online':'Offline'}</span></div><p class="small muted">${esc(u.email||'No email')}</p></div>${protectedOwner?'<span class="tag approved">OWNER</span>':`<button class="message-user" data-message-user="${esc(u.uid)}" aria-label="Message user">•••</button>`}</div><p>${esc(protectedOwner?'Verified owner · Full access':accessLabel(u.accessUntil))}</p>${payment?`<p class="small muted">Latest GCash reference: ${esc(payment.reference)} · ${esc(payment.status)}</p>`:''}${u.accessSource&&!protectedOwner?`<p class="small muted">Source: ${esc(u.accessSource)}</p>`:''}${protectedOwner?'<div class="notice">The verified owner account is protected from access changes.</div>':`<div class="row user-actions"><button class="btn secondary" data-grant-user="${esc(u.uid)}" data-days="3">+3 days</button><button class="btn secondary" data-grant-user="${esc(u.uid)}" data-days="30">+30 days</button><button class="btn secondary" data-revoke-user="${esc(u.uid)}">Revoke</button></div>`}</div>`}).join('')||'<div class="glass empty">No users match this search.</div>'}</div>`}
function paymentManagement(){return `${title('GCash Payments','OWNER','admin')}${state.payments.map(p=>`<div class="glass pad"><strong>${esc(p.name||p.email)}</strong><p>${esc(p.reference)} · ₱${esc(p.amount)}</p>${p.status==='Pending'?`<button class="btn" data-payment="${p.id}" data-payment-status="Approved">Approve 30 days</button> <button class="btn secondary" data-payment="${p.id}" data-payment-status="Rejected">Reject</button>`:badge(p.status)}</div>`).join('')}`}
function activationCodes(){return `${title('Activation Codes','OWNER','admin')}<form id="code-form" class="glass pad"><label class="field">Access days<input name="days" type="number" min="1" max="365" value="30" required></label><label class="field">Code expires<input name="expires" type="date" required></label><button class="btn wide">Generate one-time code</button></form>${state.activationCodes.map(c=>`<div class="glass pad"><strong>${esc(c.code)}</strong><p>${c.days} days · ${esc(c.expiresLabel)}</p>${!c.usedByUid&&!c.revoked?`<button data-revoke-code="${c.id}" class="link-button">Revoke</button>`:badge(c.revoked?'Revoked':'Used')}</div>`).join('')}`}
function ownerMessages(){let threads=[...new Map(state.messages.map(m=>[m.threadUid,m])).values()],list=state.messageThreadUid?state.messages.filter(m=>m.threadUid===state.messageThreadUid):state.messages;return `${title('Messages & Suggestions','OWNER','admin')}${state.messageThreadUid?'<button class="btn secondary" data-action="all-messages">← All conversations</button>':`<div class="thread-list">${threads.map(m=>`<button class="action-row" data-message-user="${esc(m.threadUid)}"><span class="grow"><strong>${esc(m.senderName||m.senderEmail||'User')}</strong><small>${esc(m.kind||'Message')} · ${esc(m.body)}</small></span><span>›</span></button>`).join('')}</div>`}<div class="message-list">${list.map(m=>`<div class="glass pad message-bubble ${m.senderUid===state.nativeUid?'owner-reply':''}"><div class="row between"><strong>${esc(m.senderName||m.senderEmail||'User')}</strong><span class="tag">${esc(m.kind||'Message')}</span></div><p>${esc(m.body)}</p></div>`).join('')||'<div class="glass empty">No messages or suggestions yet.</div>'}</div>${state.messageThreadUid?`<form class="reply-form glass pad" data-thread="${esc(state.messageThreadUid)}"><label class="field">Reply<input name="body" required maxlength="2000"></label><button class="btn wide">Send reply</button></form>`:''}`}
function appSettings(){return `${title('GCash & Updates','OWNER','admin')}<form id="settings-form" class="glass pad"><label class="field">30-day price<input name="monthlyPrice" type="number" min="1" value="${esc(state.config.monthlyPrice)}"></label><label>Show GCash <input name="gcashEnabled" type="checkbox" ${state.supportEnabled?'checked':''}></label><label>Show name <input name="showGcashName" type="checkbox" ${state.config.showGcashName?'checked':''}></label><label class="field">GCash display name<input name="gcashDisplayName" value="${esc(state.config.gcashDisplayName)}"></label><button type="button" class="btn secondary wide" data-native="pickGcashQr">Replace QR</button><label class="field">Latest version code<input name="latestVersionCode" type="number" value="${esc(state.config.latestVersionCode||2)}"></label><label class="field">Latest version name<input name="latestVersionName" value="${esc(state.config.latestVersionName||'1.0.1')}"></label><label class="field">APK URL<input name="updateUrl" type="url" value="${esc(state.config.updateUrl||'https://github.com/Kezero47/esas-reviewer-downloads/releases/download/v1.0/ESAS-Reviewer.apk')}"></label><label class="field">Release notes<textarea name="releaseNotes">${esc(state.config.releaseNotes||'Functional owner user management, 53 new Exam 14 source records with duplicates removed, and interface improvements.')}</textarea></label><button class="btn wide">Save</button></form>`}
function scanner(){return `${title('Scan & extract','OCR WORKSPACE','more')}<div class="glass pad stack"><p>Scan a page or choose a PDF/image. Review and correct the extracted text before using it as source material.</p><button class="btn wide" data-native="scan">Scan document</button><button class="btn secondary wide" data-native="pickSource">Choose PDF or image</button><label class="field">Extracted text<textarea id="scan-text" style="min-height:280px" placeholder="Recognized text appears here">${esc(state.scanText||'')}</textarea></label><button class="btn secondary wide" data-native="saveDraft">Save corrected draft on this device</button>${ownerPreview()?'<button class="btn secondary wide" data-native="pickJsonl">Validate owner JSONL draft</button>':''}<p class="footnote">A scan is a draft. Questions and answers require checking before they enter scored quizzes.</p></div>`}
function calculator(){initCalculator(state);return `<div class="calc-stage">${calculatorView(state)}</div>`}
function sourceLibrary(){let builtIn=['All','Past exams','Past board exams','Reference books','Other'],folders=[...builtIn,...state.customSourceFolders],classify=item=>item.kind==='Past exams'?'Past exams':item.kind==='Past board exams'?'Past board exams':item.kind==='Reference book'?'Reference books':'Other',items=state.sourceFolder==='All'?sourceRegistry:sourceRegistry.filter(item=>classify(item)===state.sourceFolder);return `${title('Source library','REGISTERED REFERENCES','more')}<div class="source-folders">${folders.map(folder=>`<button class="source-folder ${state.sourceFolder===folder?'active':''}" data-source-folder="${esc(folder)}"><span>▧</span><strong>${esc(folder)}</strong><small>${folder==='All'?sourceRegistry.length:sourceRegistry.filter(item=>classify(item)===folder).length} files</small></button>`).join('')}</div><form id="source-folder-form" class="glass pad source-folder-form"><label class="field">Add a new folder<input name="folder" maxlength="50" placeholder="Example: Past Board Exams"></label><button class="btn secondary wide">＋ Add folder</button><p class="footnote">Suggested filename: Past Exam – Year – Uploader Name.</p></form>${items.length?`<div class="stack">${items.map(x=>`<div class="glass pad"><div class="row between"><span class="tag">${esc(classify(x))}</span><span class="small muted">${x.pages} pages</span></div><h3 style="margin:13px 0 5px">${esc(x.title)}</h3><p class="small muted" style="margin:0">${esc(x.status)}</p></div>`).join('')}</div>`:'<div class="glass empty">This folder is ready for new approved resources.</div>'}`}
function generic(){if(state.page==='sources')return sourceLibrary();if(state.page==='bookmarks'){let questions=state.bookmarks.map(id=>questionBank.find(x=>x.id===id)).filter(Boolean);return `${title('Bookmarks','SAVED QUESTIONS & LESSONS','notes')}${state.lessonBookmarks.map(item=>`<button class="action-row" data-saved-lesson="${esc(item.key)}"><span class="grow"><strong>${esc(item.topic)}</strong><small>${esc(item.subjectName)} · Lesson</small></span><span>›</span></button>`).join('')}${questions.map(q=>`<div class="glass pad" style="margin-bottom:9px"><strong>${esc(q.prompt)}</strong><p class="small muted">${esc(subject(q.subject).name)} · Question</p></div>`).join('')||(!state.lessonBookmarks.length?'<div class="glass empty">No saved questions or lessons yet.</div>':'')}`};if(state.page==='formulas')return `${title('Saved formulas','YOUR COLLECTION','notes')}${state.notes.filter(n=>n.formula).map(n=>`<button class="action-row" data-edit-note="${n.id}">${glyph('∑','violet')}<span class="grow"><strong>${esc(n.title)}</strong><small>${esc(n.formula)}</small></span></button>`).join('')||'<div class="glass empty">Formulas you save will appear here.</div>'}`;if(state.page==='help')return `${title('Help & FAQs','GET ANSWERS','more')}<div class="glass pad"><h3>Where are my notes saved?</h3><p class="small muted">On this device in app storage.</p><h3>Why are some source questions held?</h3><p class="small muted">Unreadable or inconsistent source records stay out of scored quizzes until corrected.</p><h3>Can I use the calculator in a quiz?</h3><p class="small muted">Yes. Open the calculator overlay from the quiz without leaving the question.</p></div>`;return `${title('About ESAS Reviewer','STUDY SMARTER','more')}<div class="glass pad"><div class="brand-about"><img src="./assets/brand/logo-stacked.png" alt="ESAS Reviewer"></div><h2>Made for focused review.</h2><p class="muted">An ESAS study companion for lessons, practice, notes and calculation tools.</p></div>`}
function overlay(){if(state.overlay==='notice')return `<div class="modal-scrim"><div class="modal dialog-card" role="alertdialog" aria-modal="true"><h2>${esc(state.notice?.title||'ESAS Reviewer')}</h2><p>${esc(state.notice?.message||'')}</p><button class="btn wide" data-action="close-overlay">OK</button></div></div>`;if(state.overlay==='confirm')return `<div class="modal-scrim"><div class="modal dialog-card" role="alertdialog" aria-modal="true"><h2>${esc(state.notice?.title||'Please confirm')}</h2><p>${esc(state.notice?.message||'')}</p><div class="row"><button class="btn secondary grow" data-action="confirm-cancel">Cancel</button><button class="btn grow" data-action="confirm-ok">Confirm</button></div></div></div>`;if(state.overlay==='calculator')return `<div class="modal-scrim" data-close-overlay><div class="modal" role="dialog" aria-modal="true" aria-label="Calculator"><div class="row between"><strong>∑ Calculator</strong><button class="icon-btn" data-action="close-overlay" aria-label="Close calculator">×</button></div>${calculatorView(state,{overlay:true})}</div></div>`;if(state.overlay==='admin-tool'&&ownerPreview())return `<div class="modal-scrim" data-close-overlay><div class="modal" role="dialog" aria-modal="true"><div class="row between"><h2>${esc(state.adminTool)}</h2><button class="icon-btn" data-action="close-overlay">×</button></div>${state.adminTool==='GCash Support Settings'?`<div class="switch-row"><span>Show voluntary support section</span><button class="toggle ${state.supportEnabled?'on':''}" data-action="support-toggle" aria-label="Toggle support section"></button></div><p class="footnote">The approved QR image must be added before this section can accept support.</p>`:'<p class="muted">This management area is laid out for future backend integration.</p>'}</div></div>`;return ''}
function render(){let ownerPages=['admin','submission-detail','content-manager','content-edit','user-management','payment-management','activation-codes','owner-messages','app-settings'];if(!ownerPreview()&&ownerPages.includes(state.page))state.page='profile';document.body.dataset.theme=state.theme;if(window.NativeBridge)NativeBridge.setTheme(state.theme==='dark');document.querySelector('meta[name="theme-color"]').content=state.theme==='dark'?'#09152c':'#e9f7ff';let pages={home,rank:rankPage,reviewer,subject:subjectDetail,lesson,quiz:quizHome,'quiz-setup':paidQuizSetup,'active-quiz':activeQuiz,results,notes,'note-edit':noteEdit,'note-folders':noteFolders,'note-folder':noteFolder,'note-pinned':()=>{state.noteFilter='Pinned';return notes()},more,welcome,'download-app':downloadApp,login:()=>accountLogin('login'),register:()=>accountLogin('register'),forgot:()=>accountLogin('forgot'),profile:accountProfile,settings,support:accessSupport,admin:ownerDashboard,'submission-detail':ownerSubmission,'content-manager':contentManager,'content-edit':contentEditor,'question-library':accessQuestionLibrary,'user-management':userManagement,'payment-management':paymentManagement,'activation-codes':activationCodes,'owner-messages':ownerMessages,'app-settings':appSettings,scanner,calculator};let noNav=['welcome','login','register','forgot','active-quiz'];root.innerHTML=`<div class="app-shell"><main class="screen ${noNav.includes(state.page)?'no-nav':''}">${(pages[state.page]||generic)()}</main>${noNav.includes(state.page)?'':bottomNav()}${overlay()}</div>`;if(state.updateInfo&&!state.updatePrompted){state.updatePrompted=true;setTimeout(()=>{state.notice={title:`Update ${state.updateInfo.versionName||''} available`,message:state.updateInfo.releaseNotes||'A new ESAS Reviewer version is ready.'};state.confirmAction={type:'update',url:state.updateInfo.updateUrl||''};state.overlay='confirm';render()},100)}if(state.page==='active-quiz'&&state.session?.timer)startTick();else stopTick()}
function go(page){let ownerPages=['admin','submission-detail','content-manager','content-edit','user-management','payment-management','activation-codes','owner-messages','app-settings'];if(page==='practice'){state.quizCategory='Practice Mode';state.quizSetup.practice=true;page='quiz-setup'}if(ownerPages.includes(page)&&!ownerPreview())page='profile';if(page==='calculator')state.calcPanel='display';state.page=page;state.search='';state.filter='All';window.scrollTo(0,0);render();if(page==='user-management'&&window.NativeBridge)NativeBridge.loadUsers();if(page==='rank'&&window.NativeBridge)NativeBridge.loadLeaderboard()}
function startTick(){stopTick();tick=setInterval(()=>{let el=document.querySelector('[data-clock]');if(el&&state.session)el.textContent=formatElapsed(Date.now()-state.session.startedAt)},1000)}
function stopTick(){if(tick)clearInterval(tick);tick=null}
function formatElapsed(ms){let s=Math.floor(ms/1000);return `${String(Math.floor(s/60)).padStart(2,'0')}:${String(s%60).padStart(2,'0')}`}
function saveSession(){put('session',state.session)}
function startQuiz(){let v=state.quizSetup,{ids,choiceOrders}=createQuizSelection(availableQuestions(),v);if(!ids.length){showNotice('No questions match these filters. Choose another subject, source or type.','Quiz setup');return}state.session={ids,choiceOrders,index:0,answers:{},subjects:[...v.subjects],sources:[...(v.sources||[])],category:state.quizCategory,timer:v.timer,practice:!!v.practice,startedAt:Date.now()};saveSession();go('active-quiz')}
function finishQuiz(){let ss=state.session;if(!ss)return;let scored=scoreQuiz(questionBank,ss.ids,ss.answers);state.lastResult={ids:ss.ids,answers:ss.answers,choiceOrders:ss.choiceOrders,...scored,seconds:Math.floor((Date.now()-ss.startedAt)/1000),finishedAt:Date.now()};put('lastResult',state.lastResult);let stats=get('topicStats',{});for(const [key,value] of Object.entries(scored.topicStats)){let item=stats[key]||{attempts:0,correct:0};item.attempts+=value.attempts;item.correct+=value.correct;stats[key]=item}put('topicStats',stats);let history=get('quizHistory',[]);history.unshift({correct:scored.correct,total:scored.total,subjects:Object.keys(scored.subjectStats),finishedAt:state.lastResult.finishedAt,category:ss.category});put('quizHistory',history.slice(0,100));let percent=scored.total?Math.round(scored.correct/scored.total*100):0;if(window.NativeBridge&&state.nativeUid)NativeBridge.submitQuizResult(scored.correct,scored.total,rankForPercent(percent));state.session=null;saveSession();go('results')}
function calc(key){pressCalculatorKey(state,key);put('calcHistory',state.calcHistory);render()}
function handleAction(a){switch(a){case'theme':state.theme=state.theme==='light'?'dark':'light';put('theme',state.theme);render();break;case'guest':state.profile={name:'Guest',role:'guest'};put('profile',state.profile);put('seen',true);go('home');break;case'signout':if(signOutMode(state.profile,!!window.NativeBridge)==='native'){window.NativeBridge.signOut();return}state.profile={name:'Guest',role:'guest'};put('profile',state.profile);put('seen',false);go('welcome');break;case'toggle-owner':if(!ownerEligible())return;state.profile.role=state.profile.role==='owner-preview'?'learner-preview':'owner-preview';put('profile',state.profile);go(state.profile.role==='owner-preview'?'admin':'profile');break;case'practice-toggle':state.quizSetup.practice=!state.quizSetup.practice;render();break;case'timer-toggle':state.quizSetup.timer=!state.quizSetup.timer;render();break;case'random-toggle':state.quizSetup.random=!state.quizSetup.random;render();break;case'choice-shuffle-toggle':state.quizSetup.shuffleChoices=!state.quizSetup.shuffleChoices;render();break;case'start-quiz':startQuiz();break;case'exit-quiz':askConfirmation('Leave this quiz? Your progress will remain saved.',{type:'exit-quiz'});break;case'prev':state.session.index=Math.max(0,state.session.index-1);saveSession();render();break;case'next':state.session.index=Math.min(state.session.ids.length-1,state.session.index+1);saveSession();render();break;case'finish':finishQuiz();break;case'bookmark-review':{let qs=questionBank.filter(q=>q.subject===state.subject&&(state.reviewTopic==='All'||q.topic===state.reviewTopic));let id=qs[state.reviewIndex]?.id;if(!id)return;state.bookmarks=state.bookmarks.includes(id)?state.bookmarks.filter(x=>x!==id):[...state.bookmarks,id];put('bookmarks',state.bookmarks);render();break}case'reveal-review':state.reviewReveal=!state.reviewReveal;render();break;case'bookmark-question':{let id=state.session.ids[state.session.index];state.bookmarks=state.bookmarks.includes(id)?state.bookmarks.filter(x=>x!==id):[...state.bookmarks,id];put('bookmarks',state.bookmarks);render();break}case'calc-overlay':state.overlay='calculator';state.calcPanel='display';render();break;case'close-overlay':state.overlay=null;state.notice=null;state.confirmAction=null;render();break;case'confirm-cancel':state.overlay=null;state.notice=null;state.confirmAction=null;render();break;case'confirm-ok':{let pending=state.confirmAction;state.overlay=null;state.notice=null;state.confirmAction=null;if(pending?.type==='revoke-user'&&window.NativeBridge)NativeBridge.revokeAccess(pending.uid);if(pending?.type==='exit-quiz')go('quiz');if(pending?.type==='update'&&window.NativeBridge)NativeBridge.openUpdateLink(pending.url);else render();break}case'convert':runCalculatorOperation(state,'convert');render();break;case'support-toggle':if(!ownerPreview())return;state.supportEnabled=!state.supportEnabled;put('supportEnabled',state.supportEnabled);render();break;case'new-content':if(!ownerPreview())return;state.contentEditId=null;go('content-edit');break;case'new-note':state.editNote=null;go('note-edit');break;case'all-messages':state.messageThreadUid='';render();break;case'save-lesson':{let s=subject(state.subject),topic=state.topic||s.topics[0],key=`${s.id}::${topic}`,exists=state.lessonBookmarks.some(item=>item.key===key);state.lessonBookmarks=exists?state.lessonBookmarks.filter(item=>item.key!==key):[...state.lessonBookmarks,{key,subject:s.id,subjectName:s.name,topic}];put('lessonBookmarks',state.lessonBookmarks);render();break}case'delete-note':state.notes=state.notes.filter(n=>n.id!==state.editNote);put('notes',state.notes);state.editNote=null;go('notes');break}}
document.addEventListener('click',e=>{let t=e.target.closest('[data-action],[data-go],[data-filter],[data-subject],[data-tab],[data-topic],[data-quiz-category],[data-quiz-subject],[data-answer],[data-edit-note],[data-key],[data-history],[data-admin-filter],[data-submission],[data-status],[data-admin-tool],[data-content-filter],[data-content-folder],[data-content-id],[data-close-overlay],[data-calc-tool],[data-calc-op],[data-constant],[data-calc-control],[data-calc-select-mode],[data-calc-setting],[data-calc-clear],[data-note-filter],[data-note-folder],[data-note-pin],[data-insert],[data-review-topic],[data-review-nav],[data-quiz-source],[data-source-folder],[data-message-user],[data-saved-lesson]');if(!t)return;if(t.hasAttribute('data-close-overlay')&&e.target===t){state.overlay=null;render();return}if(t.dataset.action){handleAction(t.dataset.action);return}if(t.dataset.go){go(t.dataset.go);return}if(t.dataset.filter){state.filter=t.dataset.filter;render();return}if(t.dataset.subject){state.subject=t.dataset.subject;state.lessonTab='Lessons';state.reviewTopic='All';state.reviewIndex=0;state.reviewReveal=false;go('subject');return}if(t.dataset.tab){state.lessonTab=t.dataset.tab;render();return}if(t.dataset.reviewTopic){state.reviewTopic=t.dataset.reviewTopic;state.reviewIndex=0;state.reviewReveal=false;render();return}if(t.dataset.reviewNav){let count=questionBank.filter(q=>q.subject===state.subject&&(state.reviewTopic==='All'||q.topic===state.reviewTopic)).length;state.reviewIndex=Math.max(0,Math.min(count-1,state.reviewIndex+(t.dataset.reviewNav==='prev'?-1:1)));state.reviewReveal=false;render();return}if(t.dataset.topic){state.topic=t.dataset.topic;go('lesson');return}if(t.dataset.quizCategory){state.quizCategory=t.dataset.quizCategory;state.quizSetup.sources=state.quizCategory==='Previous Exams'?['past-exams']:[...new Set(playableQuestions.map(q=>q.sourceId))];delete state.quizSetup.source;if(state.quizCategory==='Results & History'){go('results');return}if(state.quizCategory==='Bookmarks'){go('bookmarks');return}go('quiz-setup');return}if(t.dataset.quizSubject){let available=[...new Set(playableQuestions.map(q=>q.subject))],selected=new Set(normalizeSelectedSubjects(state.quizSetup.subjects??state.quizSetup.subject,available));if(t.dataset.quizSubject==='all')selected=new Set(available);else if(selected.has(t.dataset.quizSubject)&&selected.size>1)selected.delete(t.dataset.quizSubject);else selected.add(t.dataset.quizSubject);state.quizSetup.subjects=[...selected];delete state.quizSetup.subject;render();return}if(t.dataset.quizSource){let available=[...new Set(availableQuestions().map(q=>q.sourceId))],selected=new Set(normalizeSelectedSources(state.quizSetup.sources??state.quizSetup.source,available));if(t.dataset.quizSource==='all')selected=new Set(available);else if(selected.has(t.dataset.quizSource)&&selected.size>1)selected.delete(t.dataset.quizSource);else selected.add(t.dataset.quizSource);state.quizSetup.sources=[...selected];delete state.quizSetup.source;render();return}if(t.dataset.sourceFolder){state.sourceFolder=t.dataset.sourceFolder;render();return}if(t.dataset.messageUser){state.messageThreadUid=t.dataset.messageUser;go('owner-messages');return}if(t.dataset.savedLesson){let item=state.lessonBookmarks.find(x=>x.key===t.dataset.savedLesson);if(item){state.subject=item.subject;state.topic=item.topic;go('lesson')}return}if(t.dataset.answer!==undefined){let ss=state.session,id=ss.ids[ss.index];if(ss.practice&&ss.answers[id]!==undefined)return;ss.answers[id]=Number(t.dataset.answer);saveSession();render();return}if(t.dataset.editNote){state.editNote=t.dataset.editNote;go('note-edit');return}if(t.dataset.noteFilter){state.noteFilter=t.dataset.noteFilter;render();return}if(t.dataset.noteFolder){state.selectedFolder=t.dataset.noteFolder;go('note-folder');return}if(t.dataset.notePin){let n=state.notes.find(x=>x.id===t.dataset.notePin);if(n){n.pinned=!n.pinned;put('notes',state.notes)}render();return}if(t.dataset.insert){let area=document.querySelector('#note-form textarea');if(area){let p=area.selectionStart;area.value=area.value.slice(0,p)+t.dataset.insert+area.value.slice(p);area.focus();area.setSelectionRange(p+1,p+1)}return}if(t.dataset.key){calc(t.dataset.key);return}if(t.dataset.history){let h=state.calcHistory.find(x=>x.expression===t.dataset.history);state.calcExpression=h?.template?'':t.dataset.history;state.calcTemplate=h?.template?structuredClone(h.template):null;state.calcCursor=state.calcExpression.length;state.calcAnswer=h?.answer||'0';state.calcPanel='display';render();return}if(t.dataset.adminFilter){if(!ownerPreview())return;state.adminFilter=t.dataset.adminFilter;render();return}if(t.dataset.submission){if(!ownerPreview())return;state.submissionId=t.dataset.submission;go('submission-detail');return}if(t.dataset.status){if(!ownerPreview()||state.page!=='submission-detail')return;let x=state.submissions.find(s=>s.id===state.submissionId);if(x&&window.NativeBridge){NativeBridge.reviewSubmission(x.id,t.dataset.status);go('admin');return}if(x){x.status=t.dataset.status;put('submissions',state.submissions)}go('admin');return}if(t.dataset.adminTool){if(!ownerPreview())return;state.adminTool=t.dataset.adminTool;state.overlay='admin-tool';render();return}if(t.dataset.contentFolder){if(!ownerPreview())return;state.contentFolder=t.dataset.contentFolder;render();return}if(t.dataset.contentFilter){if(!ownerPreview())return;state.contentFilter=t.dataset.contentFilter;render();return}if(t.dataset.contentId){if(!ownerPreview())return;state.contentEditId=t.dataset.contentId;go('content-edit');return}if(t.dataset.calcControl){calculatorControl(state,t.dataset.calcControl);render();return}if(t.dataset.calcSelectMode){let m=t.dataset.calcSelectMode;state.calcMode=m;const tool={STAT:'Statistics',MATRIX:'Matrix',VECTOR:'Vector',EQN:'Equation Solver',TABLE:'Table'}[m];if(tool){state.calcTool=tool;state.calcToolResult='';state.calcPanel='tool'}else state.calcPanel='display';render();return}if(t.dataset.calcSetting){state.calcAngle=t.dataset.calcSetting;state.calcPanel='display';render();return}if(t.dataset.calcClear){clearCalculatorData(state,t.dataset.calcClear);state.calcPanel='display';put('calcHistory',state.calcHistory);render();return}if(t.dataset.calcTool){state.calcTool=t.dataset.calcTool;state.calcToolResult='';state.calcPanel=state.calcTool==='Scientific Constants'?'constants':state.calcTool==='Metric Conversions'?'converter':state.calcTool==='History'?'history':'tool';render();return}if(t.dataset.calcOp){runCalculatorOperation(state,t.dataset.calcOp);put('calcHistory',state.calcHistory);render();return}if(t.dataset.constant){let p=state.calcCursor??state.calcExpression.length;state.calcExpression=state.calcExpression.slice(0,p)+t.dataset.constant+state.calcExpression.slice(p);state.calcCursor=p+t.dataset.constant.length;state.calcPanel='display';render();return}});
document.addEventListener('change',e=>{if(e.target.id==='quiz-count')state.quizSetup.count=Number(e.target.value);if(e.target.id==='quiz-source'){state.quizSetup.source=e.target.value;render()}if(e.target.id==='quiz-type'){state.quizSetup.type=e.target.value;render()}if(e.target.dataset.calcField){state.calcInputs[e.target.dataset.calcField]=e.target.value;if(e.target.dataset.calcField==='category'){delete state.calcInputs.from;delete state.calcInputs.to;state.calcToolResult='';render()}}});
document.addEventListener('input',e=>{if(e.target.dataset.calcField)state.calcInputs[e.target.dataset.calcField]=e.target.value;if(e.target.dataset.calcSearch!==undefined){state.calcSearch=e.target.value;let pos=e.target.selectionStart;render();let el=document.querySelector('[data-calc-search]');if(el){el.focus();el.setSelectionRange(pos,pos)}return}if(e.target.dataset.search){let pos=e.target.selectionStart;state.search=e.target.value;render();let input=document.querySelector(`[data-search="${e.target.dataset.search}"]`);if(input){input.focus();input.setSelectionRange(pos,pos)}}});
