document.addEventListener('click',e=>{const target=e.target.closest('[data-native]');if(!target||!window.NativeBridge)return;const action=target.dataset.native;if(action==='scan')NativeBridge.scan();if(action==='pickSource')NativeBridge.pickSource();if(action==='pickJsonl')NativeBridge.pickJsonl(JSON.stringify(questionBank.map(question=>question.id)));if(action==='publishJsonl')NativeBridge.publishJsonlDraft();if(action==='discardJsonl')NativeBridge.discardJsonlDraft();if(action==='saveDraft')NativeBridge.saveDraft(document.querySelector('#scan-text')?.value||'');if(action==='pickResourcePdf')NativeBridge.pickResourcePdf();if(action==='pickGcashQr')NativeBridge.pickGcashQr();if(action==='pickProfilePhoto')NativeBridge.pickProfilePhoto()});
document.addEventListener('click',e=>{let t=e.target.closest('[data-status],[data-download-submission],[data-payment],[data-grant-user],[data-revoke-user],[data-refresh-users],[data-revoke-code]');if(!t||!window.NativeBridge)return;if(t.dataset.status){e.stopImmediatePropagation();NativeBridge.reviewSubmission(state.submissionId,t.dataset.status,document.querySelector('#review-message')?.value?.trim()||'');go('admin');return}if(t.dataset.downloadSubmission)NativeBridge.downloadSubmission(t.dataset.downloadSubmission);if(t.dataset.payment)NativeBridge.reviewPayment(t.dataset.payment,t.dataset.paymentStatus);if(t.dataset.grantUser)NativeBridge.grantAccess(t.dataset.grantUser,Number(t.dataset.days));if(t.dataset.revokeUser)askConfirmation('Revoke this user’s full access? The account will keep free access.',{type:'revoke-user',uid:t.dataset.revokeUser});if(t.dataset.refreshUsers)NativeBridge.loadUsers();if(t.dataset.revokeCode)NativeBridge.revokeActivationCode(t.dataset.revokeCode)},true);
document.addEventListener('submit',e=>{let form=e.target;if(form.id==='login-form'&&state.page==='register'){let f=new FormData(form);if(String(f.get('password'))!==String(f.get('confirmPassword'))){e.preventDefault();e.stopImmediatePropagation();showNotice('Passwords do not match.','Account');return}}if(!window.NativeBridge)return;let f=new FormData(form);if(form.id==='submission-form'){e.preventDefault();e.stopImmediatePropagation();NativeBridge.submitResource(String(f.get('title')||''),String(f.get('category')||''),String(f.get('detail')||''),state.pickedResourceName);return}if(form.id==='payment-form'){e.preventDefault();e.stopImmediatePropagation();NativeBridge.submitPayment(String(f.get('reference')||''),Number(state.config.monthlyPrice||99));return}if(form.id==='activation-form'){e.preventDefault();e.stopImmediatePropagation();NativeBridge.redeemActivationCode(String(f.get('code')||''));return}if(form.id==='message-form'){e.preventDefault();e.stopImmediatePropagation();NativeBridge.sendMessage('',String(f.get('kind')),String(f.get('body')||''));return}if(form.classList.contains('reply-form')){e.preventDefault();e.stopImmediatePropagation();NativeBridge.sendMessage(form.dataset.thread,'Reply',String(f.get('body')||''));return}if(form.id==='code-form'){e.preventDefault();e.stopImmediatePropagation();NativeBridge.createActivationCode(Number(f.get('days')),Date.parse(`${f.get('expires')}T23:59:59`));return}if(form.id==='settings-form'){e.preventDefault();e.stopImmediatePropagation();NativeBridge.saveAppConfig(JSON.stringify({monthlyPrice:Number(f.get('monthlyPrice')),gcashEnabled:!!f.get('gcashEnabled'),showGcashName:!!f.get('showGcashName'),gcashDisplayName:String(f.get('gcashDisplayName')||''),latestVersionCode:Number(f.get('latestVersionCode')),latestVersionName:String(f.get('latestVersionName')||''),updateUrl:String(f.get('updateUrl')||''),releaseNotes:String(f.get('releaseNotes')||'')}))}},true);
document.addEventListener('click',e=>{let t=e.target.closest('[data-review-nav],[data-action="bookmark-review"]');if(!t||state.page!=='question-library')return;let qs=visibleQuestionBank().filter(q=>q.subject===state.subject);e.stopImmediatePropagation();if(t.dataset.reviewNav){state.reviewIndex=Math.max(0,Math.min(qs.length-1,state.reviewIndex+(t.dataset.reviewNav==='prev'?-1:1)));state.reviewReveal=false;render();return}let id=qs[state.reviewIndex]?.id;if(id){state.bookmarks=state.bookmarks.includes(id)?state.bookmarks.filter(x=>x!==id):[...state.bookmarks,id];put('bookmarks',state.bookmarks);render()}},true);
if(window.NativeBridge){NativeBridge.authState();NativeBridge.loadDraft();NativeBridge.loadPublishedQuestions();NativeBridge.loadAccountData()}
